CREATE procedure CF_SP_GuardarCartaOpnionSAT	@IdProveedor INT,	@Carta NVARCHAR(max),	@NombreCarta NVARCHAR(max),	@FechaExpedicion SMALLDATETIME,	@Opinion BIT,	@IdUsuario INTASBEGIN	UPDATE dbo.CF_CartaOpinionSAT		SET vigente = 0		WHERE IdProveedor = @IdProveedor	INSERT INTO dbo.CF_CartaOpinionSAT	(	    IdProveedor,	    Carta,	    NombreCarta,	    FechaExpedicion,	    Opinion,	    SubidoEl,	    SubidoPor,	    Eliminado,	    FechaEliminacion,		vigente	)	VALUES	(   @IdProveedor,                     -- IdProveedor - int	    @Carta,                   -- Carta - nvarchar(max)	    @NombreCarta,                   -- NombreCarta - nvarchar(max)	    @FechaExpedicion, -- FechaExpedicion - smalldatetime	    @Opinion,                  -- Opinion - bit	    GETDATE(), -- SubidoEl - smalldatetime	    @IdUsuario,                     -- SubidoPor - int	    0,                  -- Eliminado - bit	    NULL,  -- FechaEliminacion - smalldatetime		1	)END